var ipList = ["122.248.182.214","10.65.254.13"];

var apiKey = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJ0b2tlblV1aWQiOiI1ZTBlZDllZC00YzZmLTQ2MjYtYWRlYy0xNTExYThlZjJhMmEiLCJleHAiOjE3OTMyNjY5OTIsInV1aWQiOiJmN2NkNjRmZS00NDE4LTExZWEtYWFmNy0wMmE4NWNhZGY0NjAiLCJpYXQiOjE3NjE3MzEwMDV9.byv0-SaQ0q0bVegY6qZwAS2v3i9CA5-KNvj1dOkBOys';
var orchestratorUrl = 'https://vco206-fra1.velocloud.net/portal/';

var r = new sn_ws.RESTMessageV2();
r.setEndpoint(orchestratorUrl + '/rest/enterprise/getEnterpriseEdges');
r.setHttpMethod('POST');
r.setRequestHeader("Authorization", "Token " + apiKey);
r.setRequestHeader("Content-Type", "application/json");
r.setRequestBody(JSON.stringify({
    "enterpriseId": 9,
    "id": 32,
    "with": ["links", "site"]
}));


var res = r.execute();
var statusCode = res.getStatusCode();
var result = {};
var objDetails = {};
var objDetailsList = [];
if (statusCode == 200) {
    var edgeList = JSON.parse(res.getBody());
}

//var ipList = ["135.75.68.65", "192.168.1.1"]; // Add more IPs as needed
// var edgeList = /* your parsed JSON array from the first API */;
var matchedResults = [];

for (var i = 0; i < ipList.length; i++) {
  var ip = ipList[i];
  var matchedEdge = null;
  var matchedLink = null;

  for (var j = 0; j < edgeList.length; j++) {
    var edge = edgeList[j];
    if (!edge.links) continue;

    for (var k = 0; k < edge.links.length; k++) {
      var link = edge.links[k];
      if (link.ipAddress === ip) {
        matchedEdge = edge;
        matchedLink = link;
        break;
      }
    }

    if (matchedEdge) break;
  }

  if (matchedEdge && matchedLink) {
    matchedResults.push({
      ip: ip,
      hostname: matchedEdge.dnsName || matchedEdge.name || matchedEdge.deviceId || "Unknown",
      lat: matchedLink.lat || "",
      lon: matchedLink.lon || ""
    });
  }
}

gs.info(JSON.stringify(matchedResults));
